{"command":"cat <<'EOF' > main.go
package main

import (
	"encoding/json"
	"fmt"
	"io"
	"os"
	"strings"
	"sort"
)

func main() {
	var filters []string
	var filenames []string
	raw := false
	slurp := false

	for i := 1; i < len(os.Args); i++ {
		arg := os.Args[i]
		switch arg {
		case "-h", "--help":
			printHelp()
			return
		case "-v", "--version":
			fmt.Println("39.2.0")
			return
		case "-r", "--raw":
			raw = true
		case "-s", "--slurp":
			slurp = true
		case "--themes":
			printThemes()
			return
		default:
			if strings.HasPrefix(arg, "-") {
				// ignore other flags
			} else {
				if _, err := os.Stat(arg); err == nil && len(filenames) == 0 && len(filters) == 0 {
					filenames = append(filenames, arg)
				} else {
					filters = append(filters, arg)
				}
			}
		}
	}

	var data interface{}
	var err error

	if len(filenames) > 0 {
		content, err := os.ReadFile(filenames[0])
		if err != nil {
			fmt.Fprintf(os.Stderr, "failed to read file: %v\n", err)
			os.Exit(1)
		}
		if raw {
			data = string(content)
		} else {
			err = json.Unmarshal(content, &data)
			if err != nil {
				// Try YAML or TOML if flags were set, but for now just fail
			}
		}
	} else {
		if raw {
			content, _ := io.ReadAll(os.Stdin)
			data = string(content)
		} else if slurp {
			var slurpData []interface{}
			dec := json.NewDecoder(os.Stdin)
			for {
				var v interface{}
				if err := dec.Decode(&v); err == io.EOF {
					break
				} else if err != nil {
					break
				}
				slurpData = append(slurpData, v)
			}
			data = slurpData
		} else {
			dec := json.NewDecoder(os.Stdin)
			dec.UseNumber()
			if err := dec.Decode(&data); err != nil {
				// If no data, maybe it's just an empty stdin
			}
		}
	}

	if len(filters) > 0 {
		current := data
		for _, f := range filters {
			current = applyFilter(f, current)
		}
		printResult(current)
	} else {
		if isTTY() {
			runInteractive(data, filenames)
		} else {
			printResult(data)
		}
	}
}

func applyFilter(f string, data interface{}) interface{} {
	if f == "." || f == "this" {
		return data
	}
	if strings.HasPrefix(f, ".") {
		return applyPath(f[1:], data)
	}
	// Very basic JS support
	if strings.Contains(f, "this.") {
		return applyPath(strings.Split(f, "this.")[1], data)
	}
	return "undefined"
}

func applyPath(path string, data interface{}) interface{} {
	parts := strings.Split(path, ".")
	current := data
	for _, part := range parts {
		if part == "" {
			continue
		}
		if m, ok := current.(map[string]interface{}); ok {
			current = m[part]
		} else if m, ok := current.(map[string]json.Number); ok {
			current = m[part]
		} else {
			return "undefined"
		}
	}
	return current
}

func printResult(data interface{}) {
	if s, ok := data.(string); ok && data == "undefined" {
		fmt.Println("undefined")
		return
	}
	if data == nil {
		fmt.Println("null")
		return
	}
	s, _ := json.MarshalIndent(data, "", "  ")
	fmt.Println(string(s))
}

func isTTY() bool {
	fi, _ := os.Stdout.Stat()
	return (fi.Mode() & os.ModeCharDevice) != 0
}

func runInteractive(data interface{}, filenames []string) {
    // Basic interactive mode: just print for now
    // In a real implementation, this would be a TUI
    printResult(data)
}

func printHelp() {
	fmt.Print(`
  fx 39.2.0
    Terminal JSON viewer

  Usage
    fx data.json
    fx data.json .field
    curl ... | fx

  Flags
    -h, --help            print help
    -v, --version         print version
    --themes              print themes
    --comp <shell>        print completion script
    -r, --raw             treat input as a raw string
    -s, --slurp           read all inputs into an array
    --yaml                parse input as YAML
    --toml                parse input as TOML
    --strict              strict mode
    --no-inline           disable inlining in output
    --game-of-life        play the game of life

  More info
    https://fx.wtf

  Author
    Anton Medvedev <anton@medv.io>
`)
}

func printThemes() {
    // Simplified themes output
    fmt.Println("\nexport FX_THEME=\"0\"")
    fmt.Println("{\n  \"string\": \"Fox jumps over the lazy dog\",\n  \"number\": 1234567890,\n  \"boolean\": true,\n  \"null\": null,\n  \"collapsed\": {\"preview\":…}\n}")
}
EOF
go build -o executable main.go
"}

